    'Nav, navnîşan, telefon, e-name û daxuyaniya te diçin kesê ku agahdarî şandiye, wek ku qanûn dixwaze.',
  'copyright.counter.statement': 'Çima ew şaşî bû',
  'copyright.counter.statementHint':
    'Bibêje çima mafê te hebû ku postê parve bikî — te ew çêkiriye, destûra te heye, an ew ne karê wan e.',
  'copyright.counter.goodFaith':
    'Di bin cezaya derewê de, ez bi baweriya baş difikirim ku naverok bi şaşî an ji ber naskirineke şaş hat rakirin.',
  'copyright.counter.consent':
    'Ez dadgeha federal a herêmî ya DYA ya navnîşana xwe qebûl dikim — an, heke navnîşana min li derveyî DYA be, her herêmeke dadwerî ku Hevalo lê were dîtin — û ez ê belgeyên dadgehê ji kesê ku agahdarî şandiye an nûnerê wî qebûl bikim.',
  'copyright.counter.send': 'Bersiva dijber bişîne',
  'copyright.counter.cancel': 'Betal bike',
  'copyright.counter.sentTitle': 'Bersiva te ya dijber hat şandin.',
  'copyright.counter.sentBody':
    'Em kopiyekê ji kesê ku agahdarî şandiye re dişînin. Heke ew ji me re nebêje ku çûye dadgehê, posta te dikare ji {date} û pê ve vegere, piştî ku kesekî ji Hevalo lê nêrî.',
  'copyright.counter.done': 'Temam',
  'copyright.counter.error.already': 'Te ji bo vê berê bersiveke dijber şandiye.',
  'copyright.counter.error.closed': 'Dema şandina bersiveke dijber ji bo vê derbas bû.',
  'copyright.repeat.title': 'Kopîkirina dubare',
  'copyright.repeat.body':
    'Heke di nav diwanzdeh mehan de sê agahdariyên mafê nivîskariyê li dijî postên kesekî werin pejirandin, dibe ku em hesabê wî bigirin. Rakirineke ku piştî nirxandinê an bersiveke dijber hat betalkirin, nayê hesibandin.',
  'copyright.agent.title': 'Nûnerê DMCA',
  'copyright.agent.lead': 'Ji bo agahdariyên li gorî qanûna DMCA ya DYA, tu dikarî ji nûnerê me re jî binivîsî:',
  'copyright.contact.title': 'Pirsên din',
  'copyright.contact.more': 'Kî Hevalo pêşkêş dike, û qaîdeyên din, di vê rûpelê de ne:',
  'provider.name': 'Nav',
  'provider.tradingAs': 'bi navê bazirganiyê {name}',
  'provider.address': 'Navnîşan',
  'provider.kvk': 'Hejmara KvK (Odeya Bazirganiyê)',
  'provider.vat': 'Hejmara bacê (VAT)',
  'provider.email': 'E-name',
  'provider.phone': 'Telefon',
  'provider.agentName': 'Nûner',
  'provider.forMembers': 'Ji bo endaman',
  'provider.forAuthorities': 'Ji bo rayedaran',
  'provider.forCopyright': 'Ji bo mafê nivîskariyê',
  'provider.languages': 'Bi van zimanan binivîse: {languages}',
  'terms.summary.title': 'Bi kurtî',
  'terms.summary.kind': 'Dilnerm be. Zordarî, nefret, gef û naveroka mezinan qedexe ne.',
  'terms.summary.own':
    'Tiştên ku te çêkirine biweşîne. Gotin an wêneyê kesekî din? Tenê heke destûra te hebe — û bibêje yê kê ye.',
  'terms.summary.yours': 'Tiştê ku tu dişînî yê te dimîne. Em wî tenê nîşanî kesên ku mîhengên te destûr didin didin.',
  'terms.summary.rules':
    'Heke tu qaîdeyan bişikînî, dibe ku em postan rakin an hesabê te sînordar bikin. Em her tim sedemê ji te re dibêjin, û tu dikarî bixwazî ku em dîsa lê binêrin.',
  'terms.summary.zer': 'Zêr û gewher tenê ji bo Hevalo ne. Ew ne pereyê rastî ne.',
  'terms.summary.leave': 'Tu dikarî her dem ji Mîhengan hesabê xwe jê bibî.',
  'terms.provider.title': 'Kî Hevalo pêşkêş dike',
  'terms.provider.lead': 'Hevalo ji aliyê vê ve tê pêşkêşkirin:',
  'terms.warranty.title': 'Tenê tiştên ku destûra te heye biweşîne',
  'terms.warranty.body':
    'Dema tu tiştekî dişînî, tu soz didî ku te ew çêkiriye, an destûra te heye ku wî biweşînî: ew azad e, destûra te heye, an qanûn destûrê dide — wek gotineke kurt bi çavkaniya wê. Bê destûr wêne, huner, gotinên stranan an wergerên kesên din neweşîne.',
  'terms.licence.title': 'Tu çi destûrê didî me',
  'terms.licence.body':
    'Ji bo xebitandina Hevalo, divê em tiştê ku tu dişînî hilînin, kopî bikin (mezinahiyên biçûktir, paşeke, kopiyên li ser serverên ku wî digihînin) û nîşanî kesên ku mîhengên te destûr didin bidin. Tenê ev e: em wî nafiroşin û di reklaman de bi kar naynin. Dema tu wî jê bibî ev diqede, ji bilî paşeke û kopiyên ku qanûn ji me dixwaze demeke kurt bihêlin.',
  'terms.notices.title': 'Agahdariyên mafê nivîskariyê',
  'terms.notices.body':
    'Her kesê ku difikire tiştek li vir karê wî kopî dike, dikare li rûpela Mafê nivîskariyê, bê hesab, ji me re bibêje. Heke em ji ber agahdariyekê posta te rakin, em sedemê ji te re dibêjin, û tu dikarî bersiveke dijber bişînî an nirxandinê bixwazî.',
  'terms.notices.link': 'Here rûpela Mafê nivîskariyê',
  'terms.moderationHow':
    'Dema em tiştekî radikin an hesabê te sînordar dikin, em ji te re dibêjin çima û kîjan qaîde hat şikandin. Rapor û agahdariyên mafê nivîskariyê ji aliyê kesekî ve tên biryardan; hin kontrol, wek sînorên şandina pir bilez, otomatîk in. Tu dikarî di nav şeş mehan de ji Rewşa hesabê nirxandinê bixwazî.',
  'terms.repeat.title': 'Kopîkirina dubare',
  'terms.repeat.body':
    'Heke di nav diwanzdeh mehan de sê agahdariyên mafê nivîskariyê li dijî postên te werin pejirandin, dibe ku em hesabê te bigirin. Rakirineke ku piştî nirxandinê an bersiveke dijber hat betalkirin, nayê hesibandin.',
  'terms.shopArt.title': 'Tiştên firoşgehê',
  'terms.shopArt.body':
    'Paşxane û îkonên firoşgehê wêneyên ji bo profîla te ne, ji aliyê Hevalo ve hatine çêkirin. Dibe ku em tiştekî ji nû ve xêz bikin an ji firoşgehê derxin. Tiştên te yên te dimînin, bi wêneyê nû, û dema em tiştên ku te kirîne biguherînin, em ji te re dibêjin.',
  'terms.contact.title': 'Çawa xwe bigihînî me',
  'terms.contact.lead': 'Bi yek ji zimanên li jêr ji me re binivîse. Kesek bersiv dide.',
  'terms.law.title': 'Kîjan qanûn derbas dibe',
  'terms.law.body':
    'Ev merc di bin qanûna Holendayê de ne. Heke tu li welatekî din ê Yekîtiya Ewropayê dijî, parastina ku qanûna xerîdarên welatê te dide jî ji te re dimîne.',
